import { useQuery } from '@tanstack/react-query'
import { Wallet, ArrowUpRight, ArrowDownRight, Lock, Plus } from 'lucide-react'
import { useAuth } from '@/app/providers/AuthProvider'
import { useTenant } from '@/app/providers/TenantProvider'
import { walletService } from '@/integrations/supabase/wallet'

export function WalletPage() {
  const { user } = useAuth()
  const { manifest } = useTenant()
  const tenantId = manifest?.tenantId ?? ''

  const { data: balance } = useQuery({
    queryKey: ['wallet-balance', user?.id, tenantId],
    queryFn: () => walletService.getBalance(user!.id, tenantId),
    enabled: !!user && !!tenantId,
  })

  const { data: ledger = [] } = useQuery({
    queryKey: ['wallet-ledger', user?.id],
    queryFn: () => walletService.getLedger(user!.id),
    enabled: !!user,
  })

  const currency = balance?.currency ?? 'XCR'
  const totalEarned = ledger
    .filter((e) => e.type === 'credit')
    .reduce((sum, e) => sum + e.amount, 0)

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-3xl mx-auto">
        <h2 className="font-semibold mb-6">Wallet</h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-6">
          <div className="bg-surface rounded-xl border border-border p-5">
            <div className="flex items-center gap-2 text-muted-foreground text-xs"><Wallet size={14} /> Available</div>
            <p className="text-2xl font-bold mt-2">{(balance?.balance ?? 0).toLocaleString()} <span className="text-sm font-normal text-muted-foreground">{currency}</span></p>
          </div>
          <div className="bg-surface rounded-xl border border-border p-5">
            <div className="flex items-center gap-2 text-muted-foreground text-xs"><Lock size={14} /> Locked</div>
            <p className="text-2xl font-bold mt-2">{(balance?.lockedBalance ?? 0).toLocaleString()} <span className="text-sm font-normal text-muted-foreground">{currency}</span></p>
          </div>
          <div className="bg-surface rounded-xl border border-border p-5">
            <div className="flex items-center gap-2 text-muted-foreground text-xs">Total earned</div>
            <p className="text-2xl font-bold mt-2">{totalEarned.toLocaleString()} <span className="text-sm font-normal text-muted-foreground">{currency}</span></p>
          </div>
        </div>

        <div className="flex items-center gap-2 mb-4">
          <button className="flex items-center gap-1.5 text-sm bg-accent text-accent-foreground px-3 py-1.5 rounded-lg hover:opacity-90"><Plus size={14} /> Top up</button>
          <button className="text-sm px-3 py-1.5 rounded-lg border border-border hover:bg-muted">Withdraw</button>
        </div>

        <div className="bg-surface rounded-xl border border-border overflow-hidden">
          <div className="px-5 py-3 border-b border-border"><h3 className="font-medium text-sm">Recent activity</h3></div>
          {ledger.length === 0 ? (
            <p className="px-5 py-8 text-center text-sm text-muted-foreground">No activity yet.</p>
          ) : (
            <div className="divide-y divide-border">
              {ledger.map((e) => (
                <div key={e.id} className="flex items-center gap-3 px-5 py-3">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${e.type === 'credit' ? 'bg-success/10 text-success' : e.type === 'debit' ? 'bg-danger/10 text-danger' : 'bg-warning/10 text-warning'}`}>
                    {e.type === 'credit' ? <ArrowDownRight size={14} /> : e.type === 'lock' ? <Lock size={14} /> : <ArrowUpRight size={14} />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm truncate">{e.description}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">{new Date(e.createdAt).toLocaleDateString()}</p>
                  </div>
                  <span className={`text-sm font-medium ${e.type === 'credit' ? 'text-success' : e.type === 'debit' ? 'text-danger' : 'text-warning'}`}>
                    {e.type === 'debit' ? '-' : e.type === 'credit' ? '+' : ''}{e.amount} {currency}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
